#!/usr/bin/env bash
set -euo pipefail
python3 - <<'PY'
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,re,subprocess
cfg=Path('/root/cfg/workmate/integrated-205');baseline=json.loads((cfg/'resume-baseline-v1.json').read_text());sha=lambda b:hashlib.sha256(b).hexdigest()
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()==baseline['boot_id']
files={p:sha(Path(p).read_bytes()) for p in baseline['files']};assert files==baseline['files']
commands={}
for name,cmd in [('routes',['ip','-j','route','show','table','all']),('rules',['ip','-j','rule','show']),('iptables',['iptables-save']),('ip6tables',['ip6tables-save'])]:
 try:r=subprocess.run(cmd,capture_output=True,check=True,timeout=15)
 except (FileNotFoundError,subprocess.SubprocessError):assert baseline['commands'][name]['status']=='unavailable';commands[name]={'status':'unavailable'};continue
 data=r.stdout
 if name in ['iptables','ip6tables']:
  pattern=r'(?m)^(# (?:Generated by ip6?tables-save [^\n]+? on|Completed on) )[^\n]*$';text=data.decode();assert len(re.findall(pattern,text))>=2;data=re.sub(pattern,lambda m:m.group(1)+'<generated timestamp>',text).encode()
 assert baseline['commands'][name]['status']=='read' and sha(data)==baseline['commands'][name]['comparison_sha256'],'Live network changed; no automatic network repair is authorized'
 commands[name]={'status':'read','current_raw_sha256':sha(r.stdout),'baseline_raw_sha256':baseline['commands'][name]['sha256'],'comparison_sha256':sha(data),'all_non_timestamp_bytes_equal':True}
report={'stage':205,'status':'passed','at':datetime.now(timezone.utc).isoformat(),'files':files,'commands':commands,'network_configuration_unchanged':True,'server_boot_id_preserved':True,'baseline':'Captured resume-baseline-v1 before resumed application writes; all9 configuration hashes also match historical202 baseline.','scope':'Read-only DNS/hosts/netplan/firewall/proxy files and live routing/rules. Only iptables-generated comment times are normalized. No network setting or proxy reload was performed.'}
p=cfg/'network-preserved-v2.json';assert not p.exists();p.write_text(json.dumps(report,indent=2)+'\n');p.chmod(0o600);print(json.dumps(report))
PY
